def git(*args): return subprocess.check_output(['git',*args],cwd=ROOT,text=True).strip()
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def native(x):
    if isinstance(x,np.generic): return x.item()
    if isinstance(x,np.ndarray): return x.tolist()
    if isinstance(x,dict): return {k:native(v) for k,v in x.items()}
    if isinstance(x,(list,tuple)): return [native(v) for v in x]
    return x
def dump(n,x): OUT.mkdir(parents=True,exist_ok=True); (OUT/n).write_text(json.dumps(native(x),indent=2,sort_keys=True,allow_nan=False)+'\n')
def save(n,**x): OUT.mkdir(parents=True,exist_ok=True); np.savez_compressed(OUT/n,**x)
def l2(x): return float(np.linalg.norm(x))
def transport(a,b):
    # A bond-resolved P1 and node-vector Q have different raw shapes.  Compare
    # their existing local activity magnitudes at the same nodes, not a new field.
    aa=np.linalg.norm(a,axis=tuple(range(4,a.ndim))) if a.ndim>4 else a
    bb=np.linalg.norm(b,axis=tuple(range(4,b.ndim))) if b.ndim>4 else b
    c=np.asarray([normalized_dot(aa[t],bb[t+1]) for t in range(len(a)-1)])
    return ('CO_MOVING_PAIR' if np.all(c>0) else 'PARTIALLY_CO_MOVING' if np.any(c>0) else 'SEPARATING'),c
def phase(a,b):
    # Sign observations are used directly; a finite non-sinusoidal packet gets no fitted phase.
    aa=np.sum(a,axis=tuple(range(1,a.ndim))); bb=np.sum(b,axis=tuple(range(1,b.ndim)))
    return 'VARIABLE_PHASE' if np.any(aa*bb<0) and np.any(aa*bb>0) else 'UNRESOLVED'

